def getEnv(self, variable = None):
    var = "_EnvVar_"
    if variable:
        code = f"os.environ.get({repr(variable)})"
    else:
        code = f"dict(os.environ)"
    code = f"""#qpy:quiet
from android import *
jsla('sharedVariableSet','{var}',repr({code}))
"""
    self._rpc('executeQPyCode',code)
    from time import sleep
    sleep(1)
    var = eval(self._rpc('sharedVariableRemove',var).result)
    from .sl4a import Result
    return Result(self._id, var, None)

def notebookOpen(self, path = None):
    os = sl4a.os
    npy = os.environ["HOME"] + "/bin/NoteBook.py"
    if not os.path.exists(npy):
        npy = self.getEnv("HOME").result + "/bin/NoteBook.py"
    if path:
        return self._rpc("executeQPy", npy, os.path.abspath(path))
    return self._rpc("executeQPy", npy)